`pages/api/[route].ts` could be follows:

```ts
import { Hono } from 'hono'
import { handle } from 'hono/nextjs'

const app = new Hono()

app.get('/hello', (c) => {
  return c.json({
    message: 'Hello',
  })
})

app.get('/morning', (c) => {
  return c.json({
    message: 'Morning',
  })
